{
  "scopeId": "GUARD-POLICY-PROPOSAL-01",
  "scopeStatus": "COMPLETE",
  "scopeStatusMeaning": "Autorenumfang P1-P7 vollstaendig, keine inhaltliche Annahme oder verfahrensfehlerfreie Fremdpruefung.",
  "recommendation": "PROPOSED_NOT_ACCEPTED",
