    "path": "F:/ChnobelRuntime/specification/v2-guard-policy-01/author/proposal.md",
    "sha256": "7f376e2a9a776b6f2c303326e9b628bf0337bd2ccce1c119a7e0cb0b3ca506b3",
    "bytes": 16281
  },
  "sources": {
    "path": "F:/ChnobelRuntime/specification/v2-guard-policy-01/author/sources.json",
    "sha256": "89db2cb3d1004a667f66d12753b74c43bea466709cff39fb5f3edae9a37ce1e8",
    "bytes": 1653880
  },
  "sections": [
    {
      "id": "P1",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 2,
        "through": 5
      },
      "fulfilmentEvidence": "Prospektiver eigenstaendiger Ganztext, Kopfstatus, Normgrenzen; Leerraumwortzahl innerhalb 2200."
    },
    {
      "id": "P2",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 6,
        "through": 29
      },
      "fulfilmentEvidence": "Fuenf typisierte Beobachtungsguards mit notwendiger Kette, Negativbeleg, Unbekanntheit, passender Alternative und gemeinsamem Veto; gleicher Fachwertanker und getrennte Hilfequalifikation."
    },
    {
      "id": "P3",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 30,
        "through": 41
      },
      "fulfilmentEvidence": "Drei Kontextfakten, Abgabeereignis versus gueltige Bindung, begrenzte Fenster, Integritaetsvorrang und eigene unverkuerzte Fallbackregeln."
    },
    {
      "id": "P4",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 42,
        "through": 49
      },
      "fulfilmentEvidence": "Beide echten Ergebnisguardtexte erhalten; definitive Antwortbasis begruendet vorgeschlagen, unmittelbare Gegenprobe NOT_MATERIALISED/NOT_RUN."
    },
    {
      "id": "P5",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 50,
        "through": 60
      },
      "fulfilmentEvidence": "Alle sechs eingefrorenen Illustrationen mit wirklichen Referenzen; C-HELP-ANCHOR und C-U07 unabhaengig offen."
    },
    {
      "id": "P6",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 61,
        "through": 68
      },
      "fulfilmentEvidence": "RT-GT-01 bis 05 und Katalog-/Vertrags-/Regelpointers; bestehende ADR-Ableitung, neue Praezisierung, spaetere Integration getrennt; keine Sperre geschlossen."
    },
    {
      "id": "P7",
      "status": "COMPLETE",
      "proposalLines": {
        "from": 69,
        "through": 73
      },
      "fulfilmentEvidence": "Neue volle Ganztextvoten dreier Rollen zum selben Hash, hoechstens zwei gleichzeitig; separate Ratifikation und nachfolgend eigenes neues Manifestgate; Geschichte unveraendert und keine Implementation."
    }
  ],
